SELECT now() - INTERVAL 3 MONTH AS three_months_ago, toDate('2026-01-31') + INTERVAL 1 MONTH AS next_month, event_timestamp + INTERVAL '1 day 2 hours' AS shifted_time, INTERVAL 1 DAY + INTERVAL 6 HOUR AS composite_interval, date_add(WEEK, 2, event_date) AS two_weeks_later, dateDiff('minute', start_time, end_time) AS duration_minutes, toStartOfInterval(event_timestamp, INTERVAL 15 MINUTE) AS quarter_hour FROM anon.events_store